"use strict";

// 条形码生成器主类
function JsBarcode(element, content, options) {
    options = options || {};
    
    // 默认配置
    var defaults = {
        width: 2,
        height: 100,
        format: "CODE128",
        displayValue: true,
        fontOptions: "",
        font: "monospace",
        textAlign: "center",
        textPosition: "bottom",
        textMargin: 2,
        fontSize: 20,
        background: "#ffffff",
        lineColor: "#000000",
        margin: 10,
        marginTop: undefined,
        marginBottom: undefined,
        marginLeft: undefined,
        marginRight: undefined,
        valid: function(){}
    };

    // 合并配置
    for(var key in defaults) {
        if(!options.hasOwnProperty(key)) {
            options[key] = defaults[key];
        }
    }

    // 创建SVG元素
    function createSvg() {
        var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
        svg.setAttribute("width", "100%");
        svg.setAttribute("height", "100%");
        svg.setAttribute("viewBox", "0 0 " + (options.width * content.length + 2 * options.margin) + " " + (options.height + (options.displayValue ? options.fontSize + options.textMargin : 0) + 2 * options.margin));
        return svg;
    }

    // 生成条形码
    function generateBarcode() {
        var svg = createSvg();
        var g = document.createElementNS("http://www.w3.org/2000/svg", "g");
        svg.appendChild(g);

        // 背景
        var rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        rect.setAttribute("width", "100%");
        rect.setAttribute("height", "100%");
        rect.setAttribute("fill", options.background);
        g.appendChild(rect);

        // 生成条码
        var x = options.margin;
        for(var i = 0; i < content.length; i++) {
            var char = content.charAt(i);
            var charCode = char.charCodeAt(0);
            
            var bar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
            bar.setAttribute("x", x);
            bar.setAttribute("y", options.margin);
            bar.setAttribute("width", options.width);
            bar.setAttribute("height", options.height);
            bar.setAttribute("fill", options.lineColor);
            g.appendChild(bar);
            
            x += options.width * 1.5;
        }

        // 添加文本
        if(options.displayValue) {
            var text = document.createElementNS("http://www.w3.org/2000/svg", "text");
            text.setAttribute("x", (options.width * content.length + 2 * options.margin) / 2);
            text.setAttribute("y", options.height + options.margin + options.fontSize);
            text.setAttribute("text-anchor", "middle");
            text.setAttribute("font-family", options.font);
            text.setAttribute("font-size", options.fontSize);
            text.textContent = content;
            g.appendChild(text);
        }

        // 替换或添加到目标元素
        if(typeof element === "string") {
            element = document.querySelector(element);
        }
        if(element.tagName.toLowerCase() === "svg") {
            element.parentNode.replaceChild(svg, element);
        } else {
            element.innerHTML = "";
            element.appendChild(svg);
        }
    }

    generateBarcode();
}

